  1 │ /**
  2 │  * PF-3: a unix-socket transport for a running sidecar. Clients other than the parent that holds stdio attach with a
  3 │  * token, as one controller or as observers, and detach and attach again at will.
  4 │  *
  5 │  * Rules, each pinned by cli/test/session_socket.test.ts:
  6 │  *  - No command is parsed until the connection's first line has proved the token. A wrong, missing or malformed
  7 │  *    attach gets one fixed refusal that says nothing about why, and the connection ends.
  8 │  *  - At most one controller. Observers only watch.
  9 │  *  - A socket client can drive turns and give one yes or no per approval. It cannot raise the session's authority:
 10 │  *    no allow-always, no mode change, no slash command, no provider or model change, no shutdown.
 11 │  *  - No TCP, HTTP or WebSocket listener exists here: `listen` takes a filesystem path only.
 12 │  */
 13 │ import * as fs from "node:fs";
 14 │ import * as net from "node:net";
 15 │ import * as path from "node:path";
 16 │ import { BoundedLineReader, type LineEvent } from "./acp/jsonrpc.js";
 17 │ import { ACP_MAX_LINE_BYTES, ACP_MAX_OVERSIZED_LINES } from "./acp/types.js";
 18 │ import {
 19 │   PROTOCOL_MAX, PROTOCOL_MIN, PROTOCOL_VERSION, SIDECAR_CAPABILITIES,
 20 │   ProtocolError, encodeEvent, parseCommand, type ErrorCode, type SidecarCommand,
 21 │ } from "./protocol.js";
 22 │ import {
 23 │   newSocketName, newToken, prepareSocketPath, socketRuntimeDir, sweepStaleSockets, tokenMatches, writeDescriptor,
 24 │ } from "./core/socket_files.js";
 25 │ 
 26 │ /** Longest line before a connection has attached. An attach line is about 130 bytes. */
 27 │ export const SOCKET_MAX_PREATTACH_BYTES = 4096;
 28 │ export const SOCKET_MAX_LINE_BYTES = ACP_MAX_LINE_BYTES;
 29 │ export const SOCKET_MAX_CONNECTIONS = 8;
 30 │ export const SOCKET_ATTACH_TIMEOUT_MS = 5000;
 31 │ /** A connection with more than this queued for writing is dropped; a slow observer must not stall the session. */
 32 │ export const SOCKET_MAX_OUTBOUND_BYTES = 8 * 1024 * 1024;
 33 │ 
 34 │ export type SocketRole = "control" | "observe";
 35 │ 
 36 │ /** The one stdout line a sidecar started with `--listen` prints once the socket is bound. It never carries the token. */
 37 │ export function listeningLine(info: SocketInfo, pid: number = process.pid): string {
 38 │   return `${JSON.stringify({ v: PROTOCOL_VERSION, type: "listening", socket: info.socket, descriptor: info.descriptor, pid })}\n`;
 39 │ }
 40 │ 
 41 │ /** What the hub needs from the sidecar; `SidecarServer` is one. */
 42 │ export interface SocketSession {
 43 │   handleLine(line: string): Promise<void>;
 44 │   /** Protocol lines that bring a new client up to date: `hello`, the current `session.state`, a pending `approval.request`. */
 45 │   attachSnapshot(): { common: string[]; controller: string[] };
 46 │ }
 47 │ 
 48 │ export interface SessionSocketOptions {
 49 │   session: SocketSession;
 50 │   /** Directory for the socket and descriptor; default `socketRuntimeDir()`. */
 51 │   dir?: string;
 52 │   /** File name stem; default a random `s-<16 hex>`. */
 53 │   name?: string;
 54 │   attachTimeoutMs?: number;
 55 │   onError?: (error: unknown) => void;
 56 │ }
 57 │ 
 58 │ export interface SocketInfo {
 59 │   socket: string;
 60 │   descriptor: string;
 61 │ }
 62 │ 
 63 │ /** The commands a controller may send over the socket. `initialize` is answered by the hub; everything else here is forwarded. */
 64 │ const CONTROLLER_COMMANDS: ReadonlySet<SidecarCommand["type"]> = new Set([
 65 │   "prompt.submit", "steer", "cancel", "approve", "deny", "answer", "checkpoint.choice", "receipt", "tool.detail",
 66 │ ]);
 67 │ 
 68 │ /** The one refusal for every failed attach: it must not tell a guesser which part was wrong. */
 69 │ const REFUSAL = encodeEvent({ type: "error", code: "UNAUTHORIZED", message: "attach refused" });
 70 │ 
 71 │ interface Connection {
 72 │   id: string;
 73 │   socket: net.Socket;
 74 │   reader: BoundedLineReader;
 75 │   role?: SocketRole;
 76 │   initialized: boolean;
 77 │   oversized: number;
 78 │   timer?: ReturnType<typeof setTimeout>;
 79 │   closed: boolean;
 80 │ }
 81 │ 
 82 │ export class SessionSocketServer {
 83 │   private readonly session: SocketSession;
 84 │   private readonly server: net.Server;
 85 │   private readonly connections = new Set<Connection>();
 86 │   private controller?: Connection;
 87 │   private token = newToken();
 88 │   private socketPath?: string;
 89 │   private descriptorPath?: string;
 90 │   private socketIdentity?: { dev: number; ino: number };
 91 │   private seq = 0;
 92 │ 
 93 │   constructor(private readonly options: SessionSocketOptions) {
 94 │     this.session = options.session;
 95 │     this.server = net.createServer((socket) => this.accept(socket));
 96 │     this.server.on("error", (error) => options.onError?.(error));
 97 │   }
 98 │ 
 99 │   get connectionCount(): number {
100 │     return this.connections.size;
101 │   }
102 │ 
103 │   async listen(): Promise<SocketInfo> {
104 │     const dir = this.options.dir ?? socketRuntimeDir();
105 │     await sweepStaleSockets(dir);
106 │     const name = this.options.name ?? newSocketName();
107 │     const socketPath = path.join(dir, `${name}.sock`);
108 │     const descriptorPath = path.join(dir, `${name}.json`);
109 │     await prepareSocketPath(socketPath);
110 │     await new Promise<void>((resolve, reject) => {
111 │       this.server.once("error", reject);
112 │       this.server.listen({ path: socketPath }, () => { this.server.off("error", reject); resolve(); });
113 │     });
114 │     this.socketPath = socketPath;
115 │     try {
116 │       fs.chmodSync(socketPath, 0o600);
117 │       const stat = fs.lstatSync(socketPath);
118 │       if (!stat.isSocket() || (stat.mode & 0o777) !== 0o600) throw new Error(`socket ${socketPath} is not mode 0600`);
119 │       this.socketIdentity = { dev: stat.dev, ino: stat.ino };
120 │       this.descriptorPath = descriptorPath;
121 │       writeDescriptor(descriptorPath, { format: "nexus-socket/1", socket: socketPath, token: this.token, pid: process.pid, started_at: new Date().toISOString() });
122 │     } catch (error) {
123 │       await this.close();
124 │       throw error;
125 │     }
126 │     return { socket: socketPath, descriptor: descriptorPath };
127 │   }
128 │ 
129 │   /** Sends one already-formatted protocol line to every attached client. */
130 │   broadcast(line: string): void {
131 │     for (const connection of this.connections) {
132 │       if (connection.role) this.write(connection, line);
133 │     }
134 │   }
135 │ 
136 │   /** Stops listening, drops every client and removes the socket and descriptor. Safe to call more than once and from an exit hook. */
137 │   closeSync(): void {
138 │     for (const connection of [...this.connections]) this.drop(connection);
139 │     try { this.server.close(); } catch { /* not listening */ }
140 │     if (this.socketPath && this.socketIdentity) {
141 │       // Only the socket this server bound: a path someone else put there since is not ours to remove.
142 │       try {
143 │         const stat = fs.lstatSync(this.socketPath);
144 │         if (stat.isSocket() && stat.dev === this.socketIdentity.dev && stat.ino === this.socketIdentity.ino) fs.unlinkSync(this.socketPath);
145 │       } catch { /* already gone */ }
146 │     }
147 │     if (this.descriptorPath) { try { fs.unlinkSync(this.descriptorPath); } catch { /* already gone */ } }
148 │     this.socketPath = this.descriptorPath = this.socketIdentity = undefined;
149 │   }
150 │ 
151 │   async close(): Promise<void> {
152 │     this.closeSync();
153 │     await new Promise<void>((resolve) => (this.server.listening ? this.server.close(() => resolve()) : resolve()));
154 │   }
155 │ 
156 │   // ------------------------------------------------------------------ connections
157 │ 
158 │   private accept(socket: net.Socket): void {
159 │     if (this.connections.size >= SOCKET_MAX_CONNECTIONS) {
160 │       socket.on("error", () => {});
161 │       socket.end(encodeEvent({ type: "error", code: "BUSY", message: "too many connections" }), () => socket.destroy());
162 │       return;
163 │     }
164 │     const connection: Connection = {
165 │       id: `c${++this.seq}`, socket, reader: new BoundedLineReader(SOCKET_MAX_LINE_BYTES), initialized: false, oversized: 0, closed: false,
166 │     };
167 │     this.connections.add(connection);
168 │     connection.timer = setTimeout(() => this.refuse(connection), this.options.attachTimeoutMs ?? SOCKET_ATTACH_TIMEOUT_MS);
169 │     socket.on("data", (chunk: Buffer) => this.receive(connection, chunk));
170 │     socket.on("close", () => this.drop(connection));
171 │     socket.on("error", () => this.drop(connection));
172 │   }
173 │ 
174 │   private drop(connection: Connection): void {
175 │     if (connection.closed) return;
176 │     connection.closed = true;
177 │     if (connection.timer) clearTimeout(connection.timer);
178 │     this.connections.delete(connection);
179 │     // The session keeps running and a pending approval stays pending: the next controller is shown it again.
180 │     if (this.controller === connection) this.controller = undefined;
181 │     connection.socket.destroy();
182 │   }
183 │ 
184 │   /** Sends one last line, then closes. The connection takes no more input meanwhile, and is gone from the hub at once. */
185 │   private finish(connection: Connection, line: string): void {
186 │     if (connection.closed) return;
187 │     connection.closed = true;
188 │     if (connection.timer) clearTimeout(connection.timer);
189 │     this.connections.delete(connection);
190 │     if (this.controller === connection) this.controller = undefined;
191 │     connection.socket.on("error", () => {});
192 │     connection.socket.end(line, () => connection.socket.destroy());
193 │   }
194 │ 
195 │   private refuse(connection: Connection): void {
196 │     this.finish(connection, REFUSAL);
197 │   }
198 │ 
199 │   private write(connection: Connection, line: string): void {
200 │     if (connection.closed) return;
201 │     if (connection.socket.writableLength > SOCKET_MAX_OUTBOUND_BYTES) {
202 │       this.options.onError?.(new Error(`dropped ${connection.id}: outbound buffer over ${SOCKET_MAX_OUTBOUND_BYTES} bytes`));
203 │       this.drop(connection);
204 │       return;
205 │     }
206 │     connection.socket.write(line);
207 │   }
208 │ 
209 │   private send(connection: Connection, code: ErrorCode, message: string, id?: string): void {
210 │     this.write(connection, encodeEvent({ type: "error", ...(id ? { id } : {}), code, message }));
211 │   }
212 │ 
213 │   private receive(connection: Connection, chunk: Buffer): void {
214 │     if (connection.closed) return;
215 │     const events = connection.reader.push(chunk);
216 │     // Before the attach is proven, nothing larger than an attach line is held, whatever the reader's own cap.
217 │     if (!connection.role && connection.reader.bufferedBytes > SOCKET_MAX_PREATTACH_BYTES) return this.refuse(connection);
218 │     for (const event of events) {
219 │       if (connection.closed) return;
220 │       this.handle(connection, event);
221 │     }
222 │   }
223 │ 
224 │   private handle(connection: Connection, event: LineEvent): void {
225 │     if (!connection.role) {
226 │       if (event.kind !== "line" || Buffer.byteLength(event.text) > SOCKET_MAX_PREATTACH_BYTES) return this.refuse(connection);
227 │       return this.attach(connection, event.text);
228 │     }
229 │     if (event.kind === "oversized") {
230 │       this.send(connection, "BAD_REQUEST", `line is longer than ${SOCKET_MAX_LINE_BYTES} bytes`);
231 │       if (++connection.oversized >= ACP_MAX_OVERSIZED_LINES) this.drop(connection);
232 │       return;
233 │     }
234 │     this.command(connection, event.text);
235 │   }
236 │ 
237 │   // ------------------------------------------------------------------ attach
238 │ 
239 │   private attach(connection: Connection, text: string): void {
240 │     let message: Record<string, unknown>;
241 │     try {
242 │       const parsed = JSON.parse(text);
243 │       if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return this.refuse(connection);
244 │       message = parsed;
245 │     } catch {
246 │       return this.refuse(connection);
247 │     }
248 │     const { type, id, token, role } = message;
249 │     // Every check runs and the verdict is one boolean, so which one failed cannot be told from the outside.
250 │     const proven = tokenMatches(this.token, token);
251 │     const wellFormed = type === "attach" && typeof id === "string" && id.length > 0 && id.length <= 128 && (role === "control" || role === "observe") &&
252 │       Number.isInteger(message.v) && (message.v as number) >= PROTOCOL_MIN && (message.v as number) <= PROTOCOL_MAX;
253 │     if (!proven || !wellFormed) return this.refuse(connection);
254 │     if (role === "control" && this.controller) {
255 │       return this.finish(connection, encodeEvent({ type: "error", id: id as string, code: "BUSY", message: "another client controls this session" }));
256 │     }
257 │     if (connection.timer) clearTimeout(connection.timer);
258 │     connection.role = role as SocketRole;
259 │     if (role === "control") this.controller = connection;
260 │     this.write(connection, `${JSON.stringify({ v: PROTOCOL_VERSION, type: "attached", id, connection: connection.id, role })}\n`);
261 │     const snapshot = this.session.attachSnapshot();
262 │     for (const line of snapshot.common) this.write(connection, line);
263 │     if (role === "control") for (const line of snapshot.controller) this.write(connection, line);
264 │   }
265 │ 
266 │   // ------------------------------------------------------------------ commands
267 │ 
268 │   private command(connection: Connection, text: string): void {
269 │     let command: SidecarCommand;
270 │     try {
271 │       command = parseCommand(text);
272 │     } catch (error) {
273 │       this.send(connection, "BAD_REQUEST", (error as Error).message, error instanceof ProtocolError ? error.id : undefined);
274 │       return;
275 │     }
276 │     const id = "id" in command ? command.id : undefined;
277 │     if (command.type === "initialize") return this.initialize(connection, command);
278 │     if (connection.role !== "control") return this.send(connection, "NOT_CONTROLLER", "observers are read-only", id);
279 │     if (!CONTROLLER_COMMANDS.has(command.type)) {
280 │       return this.send(connection, "NOT_PERMITTED", `${command.type} is not available over the socket`, id);
281 │     }
282 │     if (command.type === "approve" && command.always) {
283 │       return this.send(connection, "NOT_PERMITTED", "allow-always is not available over the socket; approve once", command.id);
284 │     }
285 │     this.session.handleLine(text).catch((error) => this.options.onError?.(error));
286 │   }
287 │ 
288 │   /** Negotiation is per connection and answered here, never forwarded: the sidecar's own state belongs to its stdio parent. */
289 │   private initialize(connection: Connection, command: Extract<SidecarCommand, { type: "initialize" }>): void {
290 │     if (connection.initialized) {
291 │       return this.send(connection, "BAD_REQUEST", "initialize was already answered on this connection; a connection negotiates once.", command.id);
292 │     }
293 │     const min = command.protocol_min ?? PROTOCOL_VERSION;
294 │     const max = command.protocol_max ?? PROTOCOL_VERSION;
295 │     const protocol = Math.min(max, PROTOCOL_MAX);
296 │     if (protocol < Math.max(min, PROTOCOL_MIN)) {
297 │       return this.send(connection, "UNSUPPORTED_PROTOCOL", `No common protocol version: the client speaks ${min} to ${max}, this sidecar speaks ${PROTOCOL_MIN} to ${PROTOCOL_MAX}.`, command.id);
298 │     }
299 │     connection.initialized = true;
300 │     this.write(connection, encodeEvent({ type: "initialized", id: command.id, protocol, capabilities: [...SIDECAR_CAPABILITIES], experimental: [] }));
301 │   }
302 │ }
  1 │ /**
  2 │  * Files behind the sidecar's control socket (PF-3): the private runtime directory, the socket path, the token and the
  3 │  * descriptor that carries it. The directory is the boundary: 0700, owned by this user, never a symlink. Node cannot
  4 │  * read SO_PEERCRED, so no peer uid is checked; a process that cannot search the directory cannot connect.
  5 │  */
  6 │ import * as fs from "node:fs";
  7 │ import * as net from "node:net";
  8 │ import * as path from "node:path";
  9 │ import { randomBytes, timingSafeEqual } from "node:crypto";
 10 │ import { writePrivateFile } from "./durable_file.js";
 11 │ 
 12 │ /** `sun_path` holds 108 bytes on Linux; stay clear of the limit so the error is ours and says what to do. */
 13 │ const MAX_SOCKET_PATH = 100;
 14 │ /** A descriptor is a few hundred bytes; a client refuses anything larger. */
 15 │ export const MAX_DESCRIPTOR_BYTES = 4096;
 16 │ export const TOKEN_PATTERN = /^[0-9a-f]{64}$/;
 17 │ 
 18 │ export class SocketFilesError extends Error {
 19 │   constructor(message: string) {
 20 │     super(message);
 21 │     this.name = "SocketFilesError";
 22 │   }
 23 │ }
 24 │ 
 25 │ export interface SocketDescriptor {
 26 │   format: "nexus-socket/1";
 27 │   socket: string;
 28 │   token: string;
 29 │   pid: number;
 30 │   started_at: string;
 31 │ }
 32 │ 
 33 │ const effectiveUid = (): number => (typeof process.geteuid === "function" ? process.geteuid() : -1);
 34 │ 
 35 │ /** Throws unless `dir` is a real directory (not a symlink) owned by this user with no group or other permission bits. */
 36 │ function assertPrivateDir(dir: string, uid: number): void {
 37 │   const stat = fs.lstatSync(dir);
 38 │   if (!stat.isDirectory() || stat.isSymbolicLink() || (uid >= 0 && stat.uid !== uid) || (stat.mode & 0o077) !== 0) {
 39 │     throw new SocketFilesError(`socket directory ${dir} is not a private directory owned by this user (mode 0700, not a symlink)`);
 40 │   }
 41 │ }
 42 │ 
 43 │ function ensurePrivate(dir: string, uid: number): void {
 44 │   try { fs.mkdirSync(dir, { mode: 0o700 }); }
 45 │   catch (error: any) { if (error.code !== "EEXIST") throw error; }
 46 │   assertPrivateDir(dir, uid);
 47 │ }
 48 │ 
 49 │ /**
 50 │  * The directory sockets live in: `$XDG_RUNTIME_DIR/nexus` when that variable is an absolute path to a private
 51 │  * directory, otherwise `/tmp/nexus-sockets-<uid>` (the pattern of `clientLeasePath`). Fails closed: a directory that
 52 │  * exists but is redirected or open to others is an error, never a fallback.
 53 │  */
 54 │ export function socketRuntimeDir(env: NodeJS.ProcessEnv = process.env, uid: number = effectiveUid()): string {
 55 │   const runtime = env.XDG_RUNTIME_DIR;
 56 │   if (runtime && path.isAbsolute(runtime)) {
 57 │     assertPrivateDir(runtime, uid);
 58 │     const dir = path.join(runtime, "nexus");
 59 │     ensurePrivate(dir, uid);
 60 │     return dir;
 61 │   }
 62 │   const dir = path.join("/tmp", `nexus-sockets-${uid}`);
 63 │   ensurePrivate(dir, uid);
 64 │   if (fs.realpathSync(dir) !== dir) throw new SocketFilesError(`socket directory ${dir} is redirected`);
 65 │   return dir;
 66 │ }
 67 │ 
 68 │ /** 32 bytes of operating-system randomness, as 64 lowercase hex digits. */
 69 │ export const newToken = REDACTED string => randomBytes(32).toString("hex");
 70 │ 
 71 │ /** Constant-time comparison. A value that is not 64 lowercase hex digits never matches, and takes the same path as one that is. */
 72 │ export function tokenMatches(expected: string, offered: unknown): boolean {
 73 │   const shaped = typeof offered === "string" && TOKEN_PATTERN.test(offered);
 74 │   const a = Buffer.from(expected, "utf8");
 75 │   const b = Buffer.from(shaped ? (offered as string) : expected.replace(/./g, "0"), "utf8");
 76 │   return timingSafeEqual(a, b) && shaped;
 77 │ }
 78 │ 
 79 │ /** A fresh name: `s-<16 hex>`, well inside the socket path limit. */
 80 │ export const newSocketName = (): string => `s-${randomBytes(8).toString("hex")}`;
 81 │ 
 82 │ /** Whether something accepts connections on `socketPath`: true when a listener answers, false on ECONNREFUSED. Any other error rethrows. */
 83 │ function listenerAnswers(socketPath: string): Promise<boolean> {
 84 │   return new Promise((resolve, reject) => {
 85 │     const probe = net.connect({ path: socketPath });
 86 │     probe.once("connect", () => { probe.destroy(); resolve(true); });
 87 │     probe.once("error", (error: NodeJS.ErrnoException) => {
 88 │       probe.destroy();
 89 │       if (error.code === "ECONNREFUSED") resolve(false);
 90 │       else reject(error);
 91 │     });
 92 │   });
 93 │ }
 94 │ 
 95 │ /**
 96 │  * Makes `socketPath` safe to bind. Nothing there is the normal case. A socket owned by this user that no process
 97 │  * listens on is stale and is unlinked. Everything else is left untouched and refused: a symlink, a regular file, a
 98 │  * directory, another user's socket, and a socket a live listener answers on.
 99 │  */
100 │ export async function prepareSocketPath(socketPath: string): Promise<void> {
101 │   if (Buffer.byteLength(socketPath) > MAX_SOCKET_PATH) throw new SocketFilesError(`socket path is longer than ${MAX_SOCKET_PATH} bytes: ${socketPath}`);
102 │   let stat: fs.Stats;
103 │   try { stat = fs.lstatSync(socketPath); }
104 │   catch (error: any) { if (error.code === "ENOENT") return; throw error; }
105 │   const uid = effectiveUid();
106 │   if (!stat.isSocket() || (uid >= 0 && stat.uid !== uid)) throw new SocketFilesError(`${socketPath} exists and is not a socket owned by this user; it was left alone`);
107 │   if (await listenerAnswers(socketPath)) throw new SocketFilesError(`${socketPath} is in use by a live listener; it was left alone`);
108 │   fs.unlinkSync(socketPath);
109 │ }
110 │ 
111 │ /** Unlinks stale `s-*.sock` sockets (and their descriptors) in `dir`: sockets of this user that refuse a connection. Anything else stays. */
112 │ export async function sweepStaleSockets(dir: string): Promise<number> {
113 │   let swept = 0;
114 │   for (const name of fs.readdirSync(dir)) {
115 │     if (!/^s-[0-9a-f]{16}\.sock$/.test(name)) continue;
116 │     const socketPath = path.join(dir, name);
117 │     try {
118 │       await prepareSocketPath(socketPath); // unlinks a stale socket, throws for anything it must not touch
119 │       try { fs.unlinkSync(socketPath.replace(/\.sock$/, ".json")); } catch { /* no descriptor */ }
120 │       swept++;
121 │     } catch { /* live, foreign or unreadable: left alone */ }
122 │   }
123 │   return swept;
124 │ }
125 │ 
126 │ export function writeDescriptor(file: string, descriptor: SocketDescriptor): void {
127 │   writePrivateFile(file, `${JSON.stringify(descriptor)}\n`, { mode: 0o600 });
128 │ }
129 │ 
130 │ /** Reads a descriptor the way a client must: a regular file owned by this user, mode 0600, at most 4 KiB. */
131 │ export function readDescriptor(file: string): SocketDescriptor {
132 │   const uid = effectiveUid();
133 │   const stat = fs.lstatSync(file);
134 │   if (!stat.isFile() || stat.isSymbolicLink() || (uid >= 0 && stat.uid !== uid) || (stat.mode & 0o077) !== 0 || stat.size > MAX_DESCRIPTOR_BYTES) {
135 │     throw new SocketFilesError(`descriptor ${file} is not a private regular file owned by this user`);
136 │   }
137 │   const value = JSON.parse(fs.readFileSync(file, "utf8"));
138 │   if (value?.format !== "nexus-socket/1" || typeof value.socket !== "string" || typeof value.token !== "string" || !TOKEN_PATTERN.test(value.token)) {
139 │     throw new SocketFilesError(`descriptor ${file} is not a nexus-socket/1 descriptor`);
140 │   }
141 │   return value as SocketDescriptor;
142 │ }

