 14 │ import * as net from "node:net";
 15 │ import * as path from "node:path";
 16 │ import { BoundedLineReader, type LineEvent } from "./acp/jsonrpc.js";
 17 │ import { ACP_MAX_LINE_BYTES, ACP_MAX_OVERSIZED_LINES } from "./acp/types.js";
 18 │ import {
 19 │   PROTOCOL_MAX, PROTOCOL_MIN, PROTOCOL_VERSION, SIDECAR_CAPABILITIES,
 20 │   ProtocolError, encodeEvent, parseCommand, type ErrorCode, type SidecarCommand,
 21 │ } from "./protocol.js";
 22 │ import {
 23 │   newSocketName, newToken, prepareSocketPath, socketRuntimeDir, sweepStaleSockets, tokenMatches, writeDescriptor,
 24 │ } from "./core/socket_files.js";
 25 │ 
 26 │ /** Longest line before a connection has attached. An attach line is about 130 bytes. */
 27 │ export const SOCKET_MAX_PREATTACH_BYTES = 4096;
 28 │ export const SOCKET_MAX_LINE_BYTES = ACP_MAX_LINE_BYTES;
 29 │ export const SOCKET_MAX_CONNECTIONS = 8;
